//! `cas::noether_conservation` — Noether's theorem: conserved quantities via Poisson brackets.
//!
//! A quantity `f` is conserved under Hamiltonian dynamics generated by `H` if
//! and only if the Poisson bracket `{H, f} = 0`. This module computes Poisson
//! brackets symbolically and checks conservation.
//!
//! # Poisson bracket (1 DOF)
//!
//! For a single degree of freedom with generalized coordinate `q = Var(q_idx)`
//! and conjugate momentum `p = Var(p_idx)`:
//!
//! ```text
//! {H, f} = ∂H/∂q · ∂f/∂p − ∂H/∂p · ∂f/∂q
//! ```
//!
//! # n-DOF generalization
//!
//! For n degrees of freedom with coordinates `q₁, ..., qₙ` and momenta
//! `p₁, ..., pₙ`:
//!
//! ```text
//! {H, f} = Σᵢ (∂H/∂qᵢ · ∂f/∂pᵢ − ∂H/∂pᵢ · ∂f/∂qᵢ)
//! ```
//!
//! Results are canonicalized. Conservation is detected when the bracket
//! canonicalizes to `Const(c)` with `|c| < 1e-15`.
//!
//! # No recursion
//!
//! All traversal uses the iterative `grad` and `canonicalize` functions.

use crate::cas::canonicalize::canonicalize;
use crate::eml::eval::{eval_real, EvalCtx};
use crate::eml::grad::grad;
use crate::eml::op::LoweredOp;

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/// Result of a conservation check.
pub struct ConservationCheck {
    /// The Poisson bracket `{H, f}` (canonicalized).
    pub poisson_bracket: LoweredOp,
    /// `true` if the bracket canonicalizes to `Const(c)` with `|c| < 1e-15`.
    pub is_conserved: bool,
}

/// Error from n-DOF Poisson bracket functions.
#[derive(Debug, Clone, PartialEq)]
pub enum NoetherError {
    /// `q_indices` and `p_indices` have different lengths.
    DofMismatch,
    /// Both index slices are empty.
    EmptyDofs,
}

impl std::fmt::Display for NoetherError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            NoetherError::DofMismatch => write!(
                f,
                "q_indices and p_indices must have the same length for n-DOF Poisson bracket"
            ),
            NoetherError::EmptyDofs => write!(f, "q_indices and p_indices must be non-empty"),
        }
    }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/// Compute the 1-DOF Poisson bracket `{H, f}` symbolically.
///
/// The result is `∂H/∂q · ∂f/∂p − ∂H/∂p · ∂f/∂q` (canonicalized).
pub fn poisson_bracket_1dof(h: &LoweredOp, f: &LoweredOp, q_idx: usize, p_idx: usize) -> LoweredOp {
    let dh_dq = grad(h, q_idx);
    let dh_dp = grad(h, p_idx);
    let df_dq = grad(f, q_idx);
    let df_dp = grad(f, p_idx);

    // {H, f} = dH/dq * df/dp − dH/dp * df/dq
    let term_a = LoweredOp::Mul(Box::new(dh_dq), Box::new(df_dp));
    let term_b = LoweredOp::Mul(Box::new(dh_dp), Box::new(df_dq));
    let bracket = LoweredOp::Sub(Box::new(term_a), Box::new(term_b));

    canonicalize(&bracket).into_op()
}

/// Check whether `f` is a conserved quantity under Hamiltonian `H` (1 DOF).
///
/// `f` is conserved iff `{H, f} = 0` (Poisson bracket is identically zero).
///
/// # Detection strategy
///
/// 1. **Structural**: if the canonicalized bracket is `Const(c)` with `|c| < 1e-15`,
///    return `true` immediately.
/// 2. **Numerical fallback**: evaluate the bracket at a grid of interior sample
///    points. If all evaluations are `< 1e-9` in absolute value, the bracket is
///    treated as numerically zero (conserved). This catches cases where the CAS
///    canonicalization is not powerful enough to collapse symbolic cancellations
///    (e.g. `q·(2p) − p·(2q)` after gradient computation).
///
/// The sample grid uses `q,p ∈ {0.5, 1.0, 1.5, 2.0, 2.5}` (25 points total)
/// and only counts variables whose indices appear in the bracket expression.
pub fn check_conservation_1dof(
    h: &LoweredOp,
    f: &LoweredOp,
    q_idx: usize,
    p_idx: usize,
) -> ConservationCheck {
    let bracket = poisson_bracket_1dof(h, f, q_idx, p_idx);

    // Strategy 1: structural
    if let LoweredOp::Const(c) = &bracket {
        let is_conserved = c.abs() < 1e-15;
        return ConservationCheck {
            poisson_bracket: bracket,
            is_conserved,
        };
    }

    // Strategy 2: numerical fallback
    let n_vars = bracket.count_vars();
    let sample_pts = [0.5f64, 1.0, 1.5, 2.0, 2.5];
    let mut is_zero = true;

    'outer: for &qv in &sample_pts {
        for &pv in &sample_pts {
            let mut vars = vec![0.0f64; n_vars.max(q_idx + 1).max(p_idx + 1)];
            vars[q_idx] = qv;
            vars[p_idx] = pv;
            let ctx = EvalCtx::new(&vars);
            if let Ok(v) = eval_real(&bracket, &ctx) {
                if v.abs() > 1e-9 {
                    is_zero = false;
                    break 'outer;
                }
            }
        }
    }

    ConservationCheck {
        poisson_bracket: bracket,
        is_conserved: is_zero,
    }
}

/// Return all first integrals among a fixed set of candidates for the given
/// 1-DOF Hamiltonian.
///
/// Candidates tested:
/// - `"H"` — the Hamiltonian itself
/// - `"p"` — momentum `Var(p_idx)`
/// - `"q"` — position `Var(q_idx)`
/// - `"p²"` — `Var(p_idx)²`
/// - `"q²+p²"` — `Var(q_idx)² + Var(p_idx)²`
/// - `"q·p"` — `Var(q_idx) · Var(p_idx)`
///
/// Returns only those candidates for which `is_conserved == true`.
pub fn first_integrals_1dof(
    h: &LoweredOp,
    q_idx: usize,
    p_idx: usize,
) -> Vec<(&'static str, LoweredOp)> {
    let q = LoweredOp::Var(q_idx);
    let p = LoweredOp::Var(p_idx);

    let candidates: Vec<(&'static str, LoweredOp)> = vec![
        ("H", h.clone()),
        ("p", p.clone()),
        ("q", q.clone()),
        (
            "p²",
            LoweredOp::Mul(Box::new(p.clone()), Box::new(p.clone())),
        ),
        (
            "q²+p²",
            LoweredOp::Add(
                Box::new(LoweredOp::Mul(Box::new(q.clone()), Box::new(q.clone()))),
                Box::new(LoweredOp::Mul(Box::new(p.clone()), Box::new(p.clone()))),
            ),
        ),
        ("q·p", LoweredOp::Mul(Box::new(q), Box::new(p))),
    ];

    candidates
        .into_iter()
        .filter(|(_, candidate)| {
            let check = check_conservation_1dof(h, candidate, q_idx, p_idx);
            check.is_conserved
        })
        .collect()
}

/// Compute the n-DOF Poisson bracket `{H, f}` symbolically.
///
/// ```text
/// {H, f} = Σᵢ (∂H/∂qᵢ · ∂f/∂pᵢ − ∂H/∂pᵢ · ∂f/∂qᵢ)
/// ```
///
/// # Errors
/// - [`NoetherError::EmptyDofs`] if both slices are empty.
/// - [`NoetherError::DofMismatch`] if lengths differ.
pub fn poisson_bracket_ndof(
    h: &LoweredOp,
    f: &LoweredOp,
    q_indices: &[usize],
    p_indices: &[usize],
) -> Result<LoweredOp, NoetherError> {
    if q_indices.is_empty() || p_indices.is_empty() {
        return Err(NoetherError::EmptyDofs);
    }
    if q_indices.len() != p_indices.len() {
        return Err(NoetherError::DofMismatch);
    }

    // Accumulate the sum of 1-DOF brackets; slices non-empty so acc will be Some.
    let mut acc: Option<LoweredOp> = None;

    for (&qi, &pi) in q_indices.iter().zip(p_indices.iter()) {
        let bracket_i = poisson_bracket_1dof(h, f, qi, pi);
        acc = Some(match acc {
            None => bracket_i,
            Some(prev) => LoweredOp::Add(Box::new(prev), Box::new(bracket_i)),
        });
    }

    // SAFETY: slices are non-empty, so acc is Some at this point.
    let total = acc.ok_or(NoetherError::EmptyDofs)?;
    Ok(canonicalize(&total).into_op())
}

/// Check whether `f` is conserved under Hamiltonian `H` for n degrees of freedom.
///
/// Uses the same structural + numerical fallback strategy as
/// [`check_conservation_1dof`].
///
/// # Errors
/// See [`poisson_bracket_ndof`].
pub fn check_conservation_ndof(
    h: &LoweredOp,
    f: &LoweredOp,
    q_indices: &[usize],
    p_indices: &[usize],
) -> Result<ConservationCheck, NoetherError> {
    let bracket = poisson_bracket_ndof(h, f, q_indices, p_indices)?;

    // Strategy 1: structural
    if let LoweredOp::Const(c) = &bracket {
        let is_conserved = c.abs() < 1e-15;
        return Ok(ConservationCheck {
            poisson_bracket: bracket,
            is_conserved,
        });
    }

    // Strategy 2: numerical fallback — sample all DOF combinations
    let n_vars = bracket.count_vars();
    let sample_pts = [0.5f64, 1.0, 1.5, 2.0, 2.5];
    let mut is_zero = true;

    'outer: for &qv in &sample_pts {
        for &pv in &sample_pts {
            let max_idx = q_indices
                .iter()
                .chain(p_indices.iter())
                .copied()
                .max()
                .unwrap_or(0);
            let mut vars = vec![0.0f64; n_vars.max(max_idx + 1)];
            for &qi in q_indices {
                if qi < vars.len() {
                    vars[qi] = qv;
                }
            }
            for &pi in p_indices {
                if pi < vars.len() {
                    vars[pi] = pv;
                }
            }
            let ctx = EvalCtx::new(&vars);
            if let Ok(v) = eval_real(&bracket, &ctx) {
                if v.abs() > 1e-9 {
                    is_zero = false;
                    break 'outer;
                }
            }
        }
    }

    Ok(ConservationCheck {
        poisson_bracket: bracket,
        is_conserved: is_zero,
    })
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // Helper constructors
    fn c(v: f64) -> LoweredOp {
        LoweredOp::Const(v)
    }
    fn mul(a: LoweredOp, b: LoweredOp) -> LoweredOp {
        LoweredOp::Mul(Box::new(a), Box::new(b))
    }
    fn add(a: LoweredOp, b: LoweredOp) -> LoweredOp {
        LoweredOp::Add(Box::new(a), Box::new(b))
    }
    fn sub(a: LoweredOp, b: LoweredOp) -> LoweredOp {
        LoweredOp::Sub(Box::new(a), Box::new(b))
    }
    fn div(a: LoweredOp, b: LoweredOp) -> LoweredOp {
        LoweredOp::Div(Box::new(a), Box::new(b))
    }

    // q = Var(0), p = Var(1) throughout tests 1-7 and 10
    const Q: usize = 0;
    const P: usize = 1;

    // Free particle: H = p²/2
    fn free_particle_h() -> LoweredOp {
        let p_sq = mul(LoweredOp::Var(P), LoweredOp::Var(P));
        mul(c(0.5), p_sq)
    }

    // Harmonic oscillator: H = (p² + q²) / 2
    fn harmonic_h() -> LoweredOp {
        let p_sq = mul(LoweredOp::Var(P), LoweredOp::Var(P));
        let q_sq = mul(LoweredOp::Var(Q), LoweredOp::Var(Q));
        div(add(p_sq, q_sq), c(2.0))
    }

    // Anharmonic: H = p²/2 + q⁴/4
    fn anharmonic_h() -> LoweredOp {
        let p_sq = mul(LoweredOp::Var(P), LoweredOp::Var(P));
        let q4 = LoweredOp::Pow(Box::new(LoweredOp::Var(Q)), Box::new(c(4.0)));
        add(mul(c(0.5), p_sq), div(q4, c(4.0)))
    }

    // Test 1: Free particle H=p²/2, f=p → conserved
    #[test]
    fn test_free_particle_momentum_conserved() {
        let h = free_particle_h();
        let f = LoweredOp::Var(P);
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            check.is_conserved,
            "momentum should be conserved for free particle"
        );
    }

    // Test 2: Free particle H=p²/2, f=q → NOT conserved
    #[test]
    fn test_free_particle_position_not_conserved() {
        let h = free_particle_h();
        let f = LoweredOp::Var(Q);
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            !check.is_conserved,
            "position should NOT be conserved for free particle"
        );
    }

    // Test 3: Harmonic oscillator H=(p²+q²)/2, f=H → conserved
    #[test]
    fn test_harmonic_h_conserved() {
        let h = harmonic_h();
        let f = h.clone();
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(check.is_conserved, "H should be conserved (trivially)");
    }

    // Test 4: Harmonic oscillator f=q²+p² → conserved (proportional to H)
    #[test]
    fn test_harmonic_energy_conserved() {
        let h = harmonic_h();
        let p_sq = mul(LoweredOp::Var(P), LoweredOp::Var(P));
        let q_sq = mul(LoweredOp::Var(Q), LoweredOp::Var(Q));
        let f = add(q_sq, p_sq);
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            check.is_conserved,
            "q²+p² should be conserved for harmonic oscillator"
        );
    }

    // Test 5: Harmonic oscillator f=q → NOT conserved
    #[test]
    fn test_harmonic_position_not_conserved() {
        let h = harmonic_h();
        let f = LoweredOp::Var(Q);
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            !check.is_conserved,
            "position q should NOT be conserved for harmonic oscillator"
        );
    }

    // Test 6: Anharmonic H=p²/2+q⁴/4, f=H → conserved
    #[test]
    fn test_anharmonic_h_conserved() {
        let h = anharmonic_h();
        let f = h.clone();
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            check.is_conserved,
            "H should be conserved for anharmonic oscillator"
        );
    }

    // Test 7: Anharmonic f=p → NOT conserved (potential force is non-zero)
    #[test]
    fn test_anharmonic_momentum_not_conserved() {
        let h = anharmonic_h();
        let f = LoweredOp::Var(P);
        let check = check_conservation_1dof(&h, &f, Q, P);
        assert!(
            !check.is_conserved,
            "momentum should NOT be conserved for anharmonic oscillator"
        );
    }

    // Test 8: 2-DOF isotropic harmonic oscillator, f=angular momentum → conserved
    // Variables: q1=Var(0), q2=Var(1), p1=Var(2), p2=Var(3)
    // H = (p_x² + p_y² + x² + y²) / 2
    // L = x*p_y - y*p_x = Var(0)*Var(3) - Var(1)*Var(2)
    #[test]
    fn test_2dof_angular_momentum_conserved() {
        let x = LoweredOp::Var(0);
        let y = LoweredOp::Var(1);
        let px = LoweredOp::Var(2);
        let py = LoweredOp::Var(3);

        let px_sq = mul(px.clone(), px.clone());
        let py_sq = mul(py.clone(), py.clone());
        let x_sq = mul(x.clone(), x.clone());
        let y_sq = mul(y.clone(), y.clone());
        let h = div(add(add(add(px_sq, py_sq), x_sq), y_sq), c(2.0));

        // Angular momentum: L = x*p_y - y*p_x
        let l = sub(mul(x, py), mul(y, px));

        let check = check_conservation_ndof(
            &h,
            &l,
            &[0, 1], // q indices: x=0, y=1
            &[2, 3], // p indices: px=2, py=3
        )
        .expect("check_conservation_ndof failed");

        assert!(
            check.is_conserved,
            "angular momentum should be conserved for isotropic harmonic oscillator; bracket = {:?}",
            check.poisson_bracket
        );
    }

    // Test 9: n-DOF dim mismatch → Err(DofMismatch)
    #[test]
    fn test_ndof_dim_mismatch() {
        let h = free_particle_h();
        let f = LoweredOp::Var(1);
        let result = poisson_bracket_ndof(&h, &f, &[0, 1], &[2]); // 2 q's, 1 p → mismatch
        assert!(
            matches!(result, Err(NoetherError::DofMismatch)),
            "expected DofMismatch, got {result:?}"
        );
    }

    // Test 10: first_integrals_1dof for free particle returns H and p (at least)
    #[test]
    fn test_first_integrals_free_particle() {
        let h = free_particle_h();
        let integrals = first_integrals_1dof(&h, Q, P);
        let names: Vec<&str> = integrals.iter().map(|(name, _)| *name).collect();
        assert!(
            names.contains(&"H"),
            "free particle first integrals should include H, got {names:?}"
        );
        assert!(
            names.contains(&"p"),
            "free particle first integrals should include p, got {names:?}"
        );
    }
}
